const resources = [
  { id: 'html',   duration: 50,  dependsOn: null },
  { id: 'bundle', duration: 600, dependsOn: 'html' },
  { id: 'mount',  duration: 100, dependsOn: 'bundle' },
  { id: 'product',duration: 200, dependsOn: 'mount' },
  { id: 'title',  duration: 0,   dependsOn: 'product' }
];

function criticalPathFinish(resources, lcpId) {
  const byId = {};
  for (const r of resources) byId[r.id] = r;
  function finish(id) {
    const r = byId[id];
    const start = r.dependsOn === null ? 0 : finish(r.dependsOn);
    return start + r.duration;
  }
  return finish(lcpId);
}

console.log('LCP ' + criticalPathFinish(resources, 'title') + 'ms');
